import os, subprocess, tempfile, time, selectors
EXE='/workspace/executable'
def run(args=(), env=None, data=b'', cwd=None, seconds=1.0, limit=14000):
    e=os.environ.copy()
    if env: e.update(env)
    p=subprocess.Popen([EXE]+list(args),stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=e,cwd=cwd)
    if data:
        p.stdin.write(data); p.stdin.flush()
    sel=selectors.DefaultSelector(); sel.register(p.stdout,selectors.EVENT_READ,'out'); sel.register(p.stderr,selectors.EVENT_READ,'err')
    outputs={'out':b'', 'err':b''}; end=time.monotonic()+seconds
    while sel.get_map() and time.monotonic()<end:
        for key,_ in sel.select(.02):
            b=os.read(key.fileobj.fileno(),4096)
            if not b: sel.unregister(key.fileobj)
            else: outputs[key.data]+=b[:max(0,limit-len(outputs[key.data]))]
    timeout=p.poll() is None
    if timeout: p.kill()
    p.wait()
    for f in (p.stdin,p.stdout,p.stderr): f.close()
    return p.returncode,outputs['out'],outputs['err'],timeout

def show(label,*args,**kw):
    p=run(*args,**kw)
    print('\nCASE',label,'exit',p[0], 'timeout',p[3], '\nOUT',repr(p[1]),'\nERR',repr(p[2]))
    return p

def files(home):
    for root,dirs,ff in os.walk(home):
        dirs[:]=[x for x in dirs if x!='.git']
        for f in ff:
            path=os.path.join(root,f); print('FILE',path,repr(open(path,'rb').read()[:4000]))

