#include "app.hpp"
#include <git2.h>
#include <memory>
#include <vector>
#include <cstdlib>

namespace idea {
namespace {
template<class T, void (*Free)(T*)> struct Handle {
    T* ptr = nullptr;
    ~Handle() { if (ptr) Free(ptr); }
    operator T*() const { return ptr; }
    T** operator&() { return &ptr; }
};
using Repo = Handle<git_repository, git_repository_free>;
using Ref = Handle<git_reference, git_reference_free>;
using Object = Handle<git_object, git_object_free>;
using Index = Handle<git_index, git_index_free>;
using Tree = Handle<git_tree, git_tree_free>;
using Commit = Handle<git_commit, git_commit_free>;
using Signature = Handle<git_signature, git_signature_free>;
using Remote = Handle<git_remote, git_remote_free>;

std::string error_class(int n) {
    const char* names[] = {"None", "NoMemory", "Os", "Invalid", "Reference", "Zlib",
        "Repository", "Config", "Regex", "Odb", "Index", "Object", "Net", "Tag",
        "Tree", "Indexer", "Ssl", "Submodule", "Thread", "Stash", "Checkout",
        "FetchHead", "Merge", "Ssh", "Filter", "Revert", "Callback", "CherryPick",
        "Describe", "Rebase", "Filesystem", "Patch", "Worktree", "Sha1", "Http", "Internal"};
    if (n >= 0 && n < int(sizeof(names)/sizeof(*names))) return names[n];
    return "None";
}
std::string error_code(int n) {
    switch (n) {
    case -3: return "NotFound";
    case -4: return "Exists";
    case -5: return "Ambiguous";
    case -6: return "BufSize";
    case -7: return "User";
    case -8: return "BareRepo";
    case -9: return "UnbornBranch";
    case -10: return "Unmerged";
    case -11: return "NotFastForward";
    case -12: return "InvalidSpec";
    case -13: return "Conflict";
    case -14: return "Locked";
    case -15: return "Modified";
    case -16: return "Auth";
    case -17: return "Certificate";
    case -18: return "Applied";
    case -19: return "Peel";
    case -20: return "Eof";
    case -21: return "Invalid";
    case -22: return "Uncommitted";
    case -23: return "Directory";
    case -24: return "MergeConflict";
    case -30: return "Passthrough";
    case -31: return "IterOver";
    case -32: return "Retry";
    case -33: return "Mismatch";
    case -34: return "IndexDirty";
    case -35: return "ApplyFail";
    case -36: return "Owner";
    default: return "GenericError";
    }
}
void check(int code) {
    if (code >= 0) return;
    const git_error* e = git_error_last();
    std::string message = e && e->message ? e->message : "unknown git error";
    if (e && e->klass) message += "; class=" + error_class(e->klass) + " (" + std::to_string(e->klass) + ")";
    if (code != -1) message += "; code=" + error_code(code) + " (" + std::to_string(code) + ")";
    throw Error(message);
}
void check_string(const std::string& str) {
    if (str.find('\0') != std::string::npos)
        throw Error("data contained a nul byte that could not be represented as a string");
}

void commit_and_push(git_repository* repo, const std::string& summary) {
    out("Adding and committing your new idea to main..\n");
    Ref branch;
    int found = git_branch_lookup(&branch, repo, "main", GIT_BRANCH_LOCAL);
    if (found < 0) {
        Ref head;
        check(git_repository_head(&head, repo));
        Object target;
        check(git_reference_peel(&target, head, GIT_OBJECT_COMMIT));
        check(git_branch_create(&branch, repo, "main", reinterpret_cast<git_commit*>(target.ptr), 0));
    }
    Object target;
    check(git_reference_peel(&target, branch, GIT_OBJECT_COMMIT));
    git_checkout_options checkout = GIT_CHECKOUT_OPTIONS_INIT;
    check(git_checkout_tree(repo, target, &checkout));
    check(git_repository_set_head(repo, "refs/heads/main"));

    Index index;
    check(git_repository_index(&index, repo));
    check(git_index_add_bypath(index, "README.md"));
    check(git_index_write(index));
    git_oid tree_id;
    check(git_index_write_tree(&tree_id, index));
    Tree tree;
    check(git_tree_lookup(&tree, repo, &tree_id));
    Signature signature;
    check(git_signature_default(&signature, repo));
    Ref head;
    check(git_repository_head(&head, repo));
    Object parent;
    check(git_reference_peel(&parent, head, GIT_OBJECT_COMMIT));
    check_string(summary);
    const git_commit* parents[] = {reinterpret_cast<git_commit*>(parent.ptr)};
    git_oid commit_id;
    check(git_commit_create(&commit_id, repo, "HEAD", signature, signature, nullptr,
                            summary.c_str(), tree, 1, parents));
    out("Added and committed!\n");
    out("Pushing your new idea..\n");
    Remote remote;
    check(git_remote_lookup(&remote, repo, "origin"));
    char spec[] = "refs/heads/main:refs/heads/main";
    char* specs[] = {spec};
    git_strarray refspecs = {specs, 1};
    check(git_remote_push(remote, &refspecs, nullptr));
    out("Pushed!\n");
}
}

void view(const std::string& repo) {
    const char* pager = std::getenv("PAGER");
    run_program(pager ? pager : "less", repo + "/README.md");
}
void record(const std::string& path, const std::string& summary) {
    check(git_libgit2_init());
    check_string(path);
    Repo repo;
    check(git_repository_open(&repo, path.c_str()));
    std::string editor_error;
    try {
        const char* editor = std::getenv("EDITOR");
        run_program(editor ? editor : "vi", path + "/README.md");
    } catch (const Error& e) { editor_error = e.what(); }
    std::string save_error;
    try { commit_and_push(repo, summary); }
    catch (const Error& e) { save_error = e.what(); }
    if (!editor_error.empty()) throw Error(editor_error);
    if (!save_error.empty()) throw Error(save_error);
}
}
EOF"}

