    } catch (const Error& e) { editor_error = e.what(); }
    std::string save_error;
    try { commit_and_push(repo, summary); }
    catch (const Error& e) { save_error = e.what(); }
    if (!editor_error.empty()) throw Error(editor_error);
    if (!save_error.empty()) throw Error(save_error);
}
