std::string json_string(const std::string& text) {
    static const char* h="0123456789abcdef";
    std::string result="\"";
    for (unsigned char c: text) {
        switch(c) {
        case '\"': result+="\\\""; break;
        case '\\': result+="\\\\"; break;
        case '\b': result+="\\b"; break;
        case '\f': result+="\\f"; break;
        case '\n': result+="\\n"; break;
        case '\r': result+="\\r"; break;
        case '\t': result+="\\t"; break;
        default:
            if (c < 32) { result+="\\u00"; result+=h[c>>4]; result+=h[c&15]; }
            else result+=char(c);
        }
    }
    return result+'"';
}
std::string join(const std::string& a, const std::string& b) {
    if (a.empty()) return b;
    if (a.back()=='/') return a+b;
    return a+"/"+b;
}
void check_path(const std::string& path) {
    if (path.find('\0')!=std::string::npos) throw Error("file name contained an unexpected NUL byte");
}
}

std::string config_directory() {
    std::string base;
    const char* xdg=std::getenv("XDG_CONFIG_HOME");
    if (xdg) base=xdg;
    else {
        const char* home=std::getenv("HOME");
        if (home) base=home;
        else {
            struct passwd* user=getpwuid(getuid());
            if (!user) throw Error("Could not determine home directory");
            base=user->pw_dir;
        }
        base=join(base,".config");
    }
    // A non-directory base cannot contain an application configuration.
    if (!base.empty()) {
        struct stat st;
        if (::stat(base.c_str(),&st)==0 && !S_ISDIR(st.st_mode)) throw Error(os_error(ENOTDIR));
    }
    return join(base,"eureka");
}

std::string load_config(const std::string& directory) {
    std::string path=join(directory,"config.json");
    check_path(path);
    int fd=::open(path.c_str(), O_RDONLY | O_CLOEXEC);
    if (fd<0) throw Error(os_error(errno));
    std::string text;
    char buffer[8192];
    for (;;) {
        ssize_t n=::read(fd,buffer,sizeof(buffer));
        if (n<0) {
            if (errno==EINTR) continue;
            int e=errno; ::close(fd); throw Error(os_error(e));
        }
        if (!n) break;
        text.append(buffer,n);
    }
    ::close(fd);
    if (!valid_utf8(text)) throw Error("stream did not contain valid UTF-8");
    return Json(text).parse();
}

void setup(const std::string& directory) {
    struct stat st;
    if (::stat(directory.c_str(), &st)!=0) {
        std::error_code e;
        std::filesystem::create_directories(directory,e);
        if (e) throw Error(os_error(e.value()));
        log("DEBUG","Created config dir");
    }
    out("\033[0m\033[33m############################################################\n"
        "####                  First Time Setup                  ####\n"
        "############################################################\n\n"
        "This tool requires you to have a repository with a README.md\n"
        "in the root folder. The markdown file is where your ideas\n"
        "will be stored.\n\n"
        "Once first time setup has completed, simply run Eureka again\n"
        "to begin writing down ideas.\n        \n\033[0m");
    std::string repo;
    for (;;) {
        repo=input("Absolute path to your idea repo");
        if (repo[0]=='/') break;
        out("\033[0m\033[31mPath must be absolute\n\033[0m");
    }
    std::string path=join(directory,"config.json");
    check_path(path);
    int fd=::open(path.c_str(),O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC,0666);
    if (fd<0) throw Error(os_error(errno));
    std::string data="{\"repo\":" + json_string(repo) + "}";
    size_t pos=0;
    while (pos<data.size()) {
        ssize_t n=::write(fd,data.data()+pos,data.size()-pos);
        if (n<0) {
            if (errno==EINTR) continue;
            int e=errno; ::close(fd); throw Error(os_error(e));
        }
        pos+=n;
    }
    ::close(fd);
    log("DEBUG","Setup repo path successfully");
    out("First time setup complete. Happy ideation!\n");
}

void clear_config(const std::string& directory) {
    std::string path=join(directory,"config.json");
    if (::unlink(path.c_str())<0) throw Error(os_error(errno));
    log("DEBUG","Cleared config");
}
}
