    for (int i=0;i<int(a.size());++i) {
        for(int j=std::max(0,i-window);j<std::min(int(b.size()),i+window+1);++j) {
            if (!bm[j] && a[i]==b[j]) { am[i]=bm[j]=true; ++matches; break; }
        }
    }
    if (!matches) return 0;
    int mismatches=0, j=0;
    for (int i=0;i<int(a.size());++i) if(am[i]) {
        while(!bm[j]) ++j;
        if(a[i]!=b[j]) ++mismatches;
